import neo4j
from neo4j import GraphDatabase
from typing import Optional, Dict, Any

class Neo4jDatabase:
    def __init__(self, uri: str, user: str, password: str):
        self.driver = GraphDatabase.driver(uri, auth=(user, password))
    
    def close(self):
        self.driver.close()
    
    def create_node(self, label: str, properties: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        query = (
            f"CREATE (n:{label} $props) "
            "RETURN n.name AS name, n.id AS id, properties(n) AS props"
        )
        with self.driver.session() as session:
            result = session.run(query, props=properties)
            return result.single()
    
    def create_relationship(
        self, 
        from_label: str, 
        from_name: str, 
        to_label: str, 
        to_name: str, 
        rel_type: str, 
        properties: Dict[str, Any] = None
    ) -> Optional[Dict[str, Any]]:
        props_clause = " $rel_props" if properties else ""
        query = (
            f"MATCH (a:{from_label} {{name: $from_name}}) "
            f"MATCH (b:{to_label} {{name: $to_name}}) "
            f"CREATE (a)-[r:{rel_type}{props_clause}]->(b) "
            "RETURN type(r) AS rel_type, properties(r) AS rel_props"
        )
        with self.driver.session() as session:
            result = session.run(
                query, 
                from_name=from_name, 
                to_name=to_name, 
                rel_props=properties or {}
            )
            return result.single()
    
    def query_relationships(self, node_label: str, node_name: str) -> list:
        query = (
            f"MATCH (n:{node_label} {{name: $name}}) "
            "-[r]->(m) "
            "RETURN type(r) AS rel_type, m.name AS to_name, properties(r) AS props"
        )
        with self.driver.session() as session:
            result = session.run(query, name=node_name)
            return [record for record in result]


